import { useEffect, useState } from 'react';
import { platform } from './platform/index.js';

/**
 * Whether the device is online, kept current. For the few controls that
 * need a connection (a schedule change, a new notebook), so they can be
 * disabled with a reason rather than fail after a tap.
 */
export function useOnline(): boolean {
  const [online, setOnline] = useState(platform.network.online);
  useEffect(() => platform.network.onChange(setOnline), []);
  return online;
}
